import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        System.out.println(n * m - cal(n, m));
    }

    private static int cal(int n, int m) {
        if (n < m) {
            int temp = n;
            n = m;
            m = temp;
        }
        if (m == 1) {
            Map<Integer, Integer> dt = new HashMap<>();
            dt.put(0, 0);
            dt.put(1, 1);
            dt.put(2, 2);
            dt.put(3, 3);
            dt.put(4, 2);
            dt.put(5, 1);
            return dt.get(n % 6);
        }
        if (n == 7) {
            if (m == 2) {
                return 2;
            }
            return (n * m) % 2;
        } else if (n >= 4) {
            return (n * m) % 2;
        } else {
            Map<String, Integer> dt = new HashMap<>();
            dt.put("3,2", 2);
            dt.put("3,1", 3);
            dt.put("2,2", 4);
            dt.put("2,1", 2);
            String key = n + "," + m;
            return dt.getOrDefault(key, (n * m) % 2);
        }
    }
}
